<?php
return static function(Database $db): void {
 $p=$db->pdo; $column=static fn($name)=>(bool)$db->one('SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name="devices" AND column_name=?',[$name]);
 $p->exec("CREATE TABLE IF NOT EXISTS pc_device_pairings (id VARCHAR(64) PRIMARY KEY,pc_id VARCHAR(64) NOT NULL,device_id VARCHAR(64) NOT NULL,status ENUM('ACTIVE','REVOKED') NOT NULL DEFAULT 'ACTIVE',nickname VARCHAR(255) NULL,paired_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,revoked_at TIMESTAMP NULL,last_used_at TIMESTAMP NULL,is_default BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_pc_device_pairing(pc_id,device_id),KEY idx_pairing_pc_status(pc_id,status),KEY idx_pairing_device_status(device_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 if($column('pc_id')) { $rows=$p->query('SELECT id,pc_id,revoked_at,created_at FROM devices')->fetchAll(); foreach($rows as $r)$db->exec('INSERT IGNORE INTO pc_device_pairings(id,pc_id,device_id,status,paired_at,revoked_at) VALUES(?,?,?,?,?,?)',[Util::id(),$r['pc_id'],$r['id'],$r['revoked_at']?'REVOKED':'ACTIVE',$r['created_at'],$r['revoked_at']]); $old=(int)$p->query('SELECT COUNT(*) FROM devices')->fetchColumn();$new=(int)$p->query('SELECT COUNT(*) FROM pc_device_pairings')->fetchColumn();if($old!==$new)throw new RuntimeException("pairing migration mismatch old=$old new=$new"); $p->exec('ALTER TABLE devices DROP FOREIGN KEY fk_devices_pc');$p->exec('ALTER TABLE devices DROP COLUMN pc_id'); }
 if(!$column('stable_identity'))$p->exec('ALTER TABLE devices ADD stable_identity CHAR(64) NULL AFTER id');$p->exec("UPDATE devices SET stable_identity=SHA2(CONCAT('key:',public_key_pem),256) WHERE stable_identity IS NULL");$p->exec('ALTER TABLE devices MODIFY stable_identity CHAR(64) NOT NULL, ADD UNIQUE KEY uq_devices_stable_identity(stable_identity)');
 if($column('revoked_at'))$p->exec('ALTER TABLE devices CHANGE revoked_at revoked_globally_at TIMESTAMP NULL DEFAULT NULL'); if(!$column('last_seen_at'))$p->exec('ALTER TABLE devices ADD last_seen_at TIMESTAMP NULL');
};
